// Usa sempre a linha MAIS NOVA que o gatilho trouxe (o gatilho pode trazer várias; a primeira é a mais antiga).
const linhas = $('Nova resposta do formulário').all();
const r = linhas[linhas.length - 1].json;
const pega = (frag) => { const k = Object.keys(r).find(k => k.toLowerCase().includes(frag)); return k ? String(r[k] || '').trim() : ''; };
// Todos os e-mails que aparecem em qualquer resposta: o do Google (Endereço de e-mail) e o que a pessoa digitou.
const reEmail = /[^\s@<>(),;:"']+@[^\s@<>(),;:"']+\.[a-z]{2,}/gi;
const emails = [...new Set(Object.values(r).flatMap(v => String(v || '').match(reEmail) || []).map(e => e.toLowerCase()))];
let nome = pega('nome completo') || pega('nome');
if (nome.includes('@')) nome = '';
const primeiro = (nome.split(/\s+/)[0] || '').replace(/[^\p{L}]/gu, '');
const partes = emails.map(e => 'contato_email.ilike.' + encodeURIComponent(e));
if (primeiro.length >= 3) partes.push('titulo.ilike.*' + encodeURIComponent(primeiro) + '*');
const filtro = partes.length ? partes.join(',') : 'titulo.eq.__nada__';
const texto = Object.entries(r).filter(([k, v]) => v !== '' && v != null && !/^row_number$/i.test(k)).map(([k, v]) => `${k}\n${v}`).join('\n\n');
return [{ json: { email: emails[0] || '', emails, nome: nome || emails[0] || '', texto, filtro, linha: r.row_number || null } }];

const x = $('Lê resposta').item.json;
const todos = ($input.all() || []).map(i => i.json).filter(c => c && c.id);
const porEmail = todos.filter(c => (x.emails || []).includes((c.contato_email || '').trim().toLowerCase()));
const porNome = todos.filter(c => x.nome && !x.nome.includes('@') && String(c.titulo || '').toLowerCase().split(/\s+/).slice(0, 2).every(p => x.nome.toLowerCase().includes(p)));
const cards = porEmail.length ? porEmail : porNome;
const card = cards.length === 1 ? cards[0] : null;
let tel = String((card && card.contato_whatsapp) || '').replace(/\D/g, '');
if (tel && (tel.length === 10 || tel.length === 11)) tel = '55' + tel;
// Escopo contratado (ficha do cliente, aba Clientes) vale mais que o da proposta (card do pipeline).
const slugsDe = (c) => { const doCliente = (c.clientes || []).flatMap(cl => (cl.cliente_produtos || []).map(p => (p.produtos || {}).slug || '')).filter(Boolean); return doCliente.length ? doCliente : (c.oportunidade_produtos || []).map(p => (p.produtos || {}).slug || '').filter(Boolean); };
const slugs = card ? slugsDe(card) : [];
const arco = slugs.some(s => s.startsWith('arco'));
return [{ json: { ok: !!card, qtd: cards.length, card_id: card ? card.id : null, cliente: card ? card.titulo : x.nome, primeiro: String((card ? card.titulo : x.nome) || '').split(/\s+/)[0], tel, email: x.email, texto: x.texto,
  trafego: !arco && slugs.some(s => s.startsWith('trafego')), pagina: !arco && slugs.includes('pagina-vendas'), arco } }];

const d = $('Acha o card').first().json;
const rodape = 'Criada automaticamente quando o cliente preencheu o formulário de diagnóstico.' + (d.card_id ? `\nCard no CRM: ${d.card_id}` : '');
return [{ json: { cliente: d.cliente, trafego: !!d.trafego, pagina: !!d.pagina, rodape } }];

const r = $('OpenAI · resumo').first().json || {};
let t = r.output_text || '';
if (!t && Array.isArray(r.output)) t = r.output.flatMap(o => (o.content || []).map(c => c.text || '')).join('
').trim();
const res = ($('Cria no gestão').first().json || {}).r || {};
const d = $('Acha o card').first().json;
// Sempre devolve um item: sem tarefa de análise o comentário falha, mas o aviso no WhatsApp ainda segue.
return [{ json: { task_id: res.analise_id || '', comment_text: ('RESUMO DA IA

' + (t || '(a IA não respondeu; leia as respostas abaixo)') + '

---

RESPOSTAS DO FORMULÁRIO

' + d.texto).slice(0, 95000) } }];

